{
  "claims": [
    {
      "claim": "The Kannan–Lovász–Simonovits (KLS) conjecture was proposed in 1995.",
      "sourceUrl": "https://www.microsoft.com/en-us/research/blog/solving-a-31-year-old-grand-challenge-in-mathematics-the-kls-conjecture",
      "excerpt": "The Kannan–Lovász–Simonovits (KLS) conjecture was proposed in 1995."
    },
    {
      "claim": "The KLS conjecture asks whether the best flat or hyperplane cut is always nearly as effective as the best cut of any shape for a broad class of high-dimensional probability distributions.",
      "sourceUrl": "https://www.microsoft.com/en-us/research/blog/solving-a-31-year-old-grand-challenge-in-mathematics-the-kls-conjecture",
      "excerpt": "It asks whether, for a broad class of high-dimensional probability distributions, the best flat or hyperplane cut is always nearly as effective as the best cut of any shape."
    },
    {
      "claim": "Prior to the complete proof, a result established in July 2026 allowed the bound to grow slowly as dimensions increased.",
      "sourceUrl": "https://www.microsoft.com/en-us/research/blog/solving-a-31-year-old-grand-challenge-in-mathematics-the-kls-conjecture",
      "excerpt": "Before this work, the best known result, established in July 2026, allowed that bound to grow slowly as the number of dimensions increased."
    },
    {
      "claim": "In the October 1, 2026 version of the paper, the recursive application reduced the dependence on dimension to the iterated logarithm.",
      "sourceUrl": "https://www.microsoft.com/en-us/research/blog/solving-a-31-year-old-grand-challenge-in-mathematics-the-kls-conjecture",
      "excerpt": "In the October 1, 2026 version of the paper, this reduced the dependence on dimension to the iterated logarithm."
    },
    {
      "claim": "The complete proof eliminating the dependence on the number of dimensions was achieved in the October 4, 2026 version of the paper.",
      "sourceUrl": "https://www.microsoft.com/en-us/research/blog/solving-a-31-year-old-grand-challenge-in-mathematics-the-kls-conjecture",
      "excerpt": "This eliminated the dependence on the number of dimensions and completed the proof in the October 4, 2026 version of the paper."
    }
  ]
}
